import type {HandoffScope} from './cashier-handoff';
export type CashJournalSource={scope:HandoffScope;kind:'opening'|'custody';source:string;account:string};
export type CashJournalCandidate={journal_id:string;posting_date:string;description:string;cash_minor:string};
export function readCashJournalCandidates(value:unknown,s:CashJournalSource,before:string|null=null){if(!value||typeof value!=='object')throw Error('Invalid journal candidates.');const r=value as Record<string,unknown>;if(r.schema_version!==1||r.tenant_id!==s.scope.tenant||r.property_id!==s.scope.property||r.actor_id!==s.scope.actor||r.kind!==s.kind||r.source_id!==s.source||r.account_id!==s.account||typeof r.cash_minor!=='string'||! /^-?\d+$/.test(r.cash_minor)||BigInt(r.cash_minor)===BigInt(0)||typeof r.business_date!=='string'||! /^\d{4}-\d{2}-\d{2}$/.test(r.business_date)||typeof r.already_linked!=='boolean'||typeof r.has_more!=='boolean'||!Array.isArray(r.entries)||r.entries.length>50)throw Error('Journal candidates do not match this cash source.');let previous=before;const entries:CashJournalCandidate[]=r.entries.map(v=>{const e=v as CashJournalCandidate;if(!e||typeof e.journal_id!=='string'||! /^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(e.journal_id)||previous!==null&&e.journal_id>=previous||typeof e.posting_date!=='string'||! /^\d{4}-\d{2}-\d{2}$/.test(e.posting_date)||e.posting_date>(r.business_date as string)||typeof e.description!=='string'||!e.description.trim()||e.cash_minor!==r.cash_minor)throw Error('Invalid candidate journal.');previous=e.journal_id;return e;});if(r.already_linked&&entries.length||r.has_more&&(entries.length!==50||r.next_cursor!==entries[49].journal_id)||!r.has_more&&r.next_cursor!==null)throw Error('Invalid candidate page.');return {entries,next:r.has_more?r.next_cursor as string:null,linked:r.already_linked,cash:r.cash_minor};}
